      const query = item.item_name.toLowerCase();
      if (!query) {
        return this.masterItems;
      } else {
        return this.masterItems.filter(masterItem => masterItem.item_name.toLowerCase().includes(query) || masterItem.item_code.toLowerCase().includes(query) || masterItem.category_name && masterItem.category_name.toLowerCase().includes(query));
